import * as M from './model.js';
import {inspectPayload} from './save-vault.js';

export function createSaveUI(api){
 const {vault,getState,setModal,btn,esc,toast}=api;let selected=null,manualIndex=null;
 const details=meta=>`<div class="save-preview"><p><b>${esc(meta.name)} 선생님</b><br>${meta.grade}학년 · 학생 ${meta.count}명</p><p><b>${meta.year}학년도</b><br>${M.dateLabel({day:meta.day})} ${M.clock(meta.minute)}</p><p>준비물 잔액 <b>${meta.budget.toLocaleString('ko-KR')}원</b></p><p>수업 기록 <b>${meta.lessons}개</b> · 인물 메모 <b>${meta.notes}개</b></p></div>`;
 function hub(){const {source,rows}=vault.slots(),recovery=api.needsRecovery();const renderRow=row=>`<article class="save-slot"><h3>${esc(row.title)}</h3>${row.valid?`<p><b>${esc(row.meta.name)} 선생님</b> · ${row.meta.grade}학년</p><small>${row.meta.year}학년도 · ${M.dateLabel({day:row.meta.day})} ${M.clock(row.meta.minute)}</small><small>${row.meta.count}명 · ${esc(row.record.label||'자동 기록')}</small>`:row.empty?'<p>비어 있는 저장 칸</p>':'<p class="save-status error">기록을 확인하지 못했습니다.</p>'}<div class="buttons">${row.valid?btn('미리 보고 불러오기','vault-preview',`data-id="${row.id}"`):''}${row.id.startsWith('manual:')&&!recovery?btn(row.empty?'여기에 저장':'현재 교실로 교체','vault-manual',`data-id="${row.id.split(':')[1]}"`):''}</div></article>`;
  setModal('저장과 교실 이어하기',`${recovery?'<p class="save-status error">마지막 저장을 읽지 못해 자동 저장을 멈췄습니다. 원본은 유지되어 있습니다. 다른 기록을 미리 본 뒤 선택하거나 저장 파일을 가져오세요.</p>':''}${source.blocked?`<p class="save-status error">${esc(source.error)}</p>`:''}<p class="intro">자동 저장은 최근 3개 시점을, 수동 저장은 원하는 교실 3개를 보관합니다. 불러오기 전 날짜·학급·예산을 확인하세요.</p><h3>자동 저장</h3><div class="save-grid">${rows.filter(r=>r.id.startsWith('auto:')).map(renderRow).join('')||'<p>첫 저장을 마치면 기록이 생깁니다.</p>'}</div><h3>수동 저장</h3><div class="save-grid">${rows.filter(r=>r.id.startsWith('manual:')).map(renderRow).join('')}</div>${rows.some(r=>r.id==='legacy')?'<h3>이전 저장에서 복구</h3><div class="save-grid">'+rows.filter(r=>r.id==='legacy').map(renderRow).join('')+'</div>':''}<div class="buttons">${!recovery?btn('현재 교실 파일 내려받기','export-save'):''}${btn('저장 파일 가져오기','import-save')}${btn('저장 원본 묶음 내려받기','vault-originals')}${btn('설정','settings')}</div><p class="intro">이 기기·브라우저에만 저장됩니다. GitHub Pages와 기존 실행 사이트는 저장 공간이 다르므로 파일 내보내기·가져오기로 옮겨 주세요.</p>`,'자동 3칸 · 수동 3칸 · 원본 보존',true,{key:'save-vault'});
 }
 function preview(id){const row=vault.candidate(id);if(!row.valid){toast(row.error);return;}selected={payload:row.record.payload,title:row.title,meta:row.meta};showPreview();}
 function showPreview(){if(!selected)return;setModal('불러올 교실 미리보기',`${details(selected.meta)}<p class="notice">${esc(selected.title)} · 저장 버전 ${esc(selected.meta.version)} → 현재 ${M.VERSION}. 학생·대화·인물 메모·출결·예산·사용한 휴가는 이 기록의 시점으로 돌아갑니다. 확인만으로 현재 교실이 바뀌지 않습니다.</p><div class="buttons right">${btn('돌아가기','vault-open')}${btn('이 기록으로 이어하기','vault-restore','','primary')}</div>`,'확인 후 복구',true,{key:'save-preview'});}
 function previewFile(payload){const row=inspectPayload(payload);if(!row.valid){toast(row.error);return false;}selected={payload,title:'가져온 저장 파일',meta:row.meta};showPreview();return true;}
 function manual(index){manualIndex=Number(index);if(!Number.isInteger(manualIndex)||manualIndex<0||manualIndex>2)return;const current=inspectPayload(JSON.stringify(getState()));if(!current.valid){toast(current.error);return;}const before=vault.slots().rows.find(r=>r.id==='manual:'+manualIndex);setModal('수동 저장 '+(manualIndex+1),`${details(current.meta)}${before?.valid?`<p class="notice">이 칸의 ${esc(before.meta.name)} 선생님 · ${M.dateLabel({day:before.meta.day})} 기록을 현재 교실로 바꿉니다. 다른 수동 저장 칸은 유지됩니다.</p>`:'<p class="notice">현재 교실을 선택한 칸에 보관합니다.</p>'}<label class="form-field">저장 이름<input id="vault-label" maxlength="60" value="${esc(before?.record?.label||'우리 반 기록')}" placeholder="예: 공개수업을 준비하며"></label><div class="buttons right">${btn('취소','vault-open')}${btn('이 칸에 저장','vault-manual-confirm','','primary')}</div>`,'날짜와 학급 확인',true,{key:'manual-save'});}
 function handle(action,id){
  if(action==='vault-open'){hub();return;}
  if(action==='vault-preview'){preview(id);return;}
  if(action==='vault-manual'){manual(id);return;}
  if(action==='vault-manual-confirm'){if(!api.save())return;const label=document.querySelector('#vault-label')?.value||'',r=vault.write(getState(),{manual:manualIndex,label});if(!r.ok){toast(r.error);return;}hub();toast('수동 저장 '+(manualIndex+1)+'에 교실을 보관했습니다.');return;}
  if(action==='vault-restore'){if(!selected)return;if(!api.needsRecovery()&&!api.save())return;const r=vault.importSave(selected.payload);if(!r.ok){toast(r.error);return;}selected=null;api.apply(r.state);toast('확인한 기록으로 교실을 불러왔습니다.');return;}
  if(action==='vault-originals'){api.download(vault.rawBackup(),'오늘우리교실은_저장원본.json');toast('저장 원본 묶음을 내려받았습니다. 일반 게임 저장 파일과 구분해 보관하세요.');return;}
 }
 return {hub,previewFile,handle};
}
